// Typed, off-main-thread access to the Rust core (`MobileDevice`, generated by
// UniFFI into Generated/Bindings). Every request is one JSON object with an
// `op`; every reply is `{ok: true, ...}` or `{ok: false, error}`, or a thrown
// `MobileError`. No other backend exists: if the core can't open, the app
// shows the error.

import Foundation
import UIKit

extension CoreFailure {
    init(_ error: Error) {
        if let failure = error as? CoreFailure {
            self = failure
            return
        }
        if let error = error as? MobileError {
            // Each case carries the core's own plain sentence as `message`.
            let child = Mirror(reflecting: error).children.first
            let message = child.flatMap {
                $0.value as? String ?? Mirror(reflecting: $0.value).children.first?.value as? String
            }
            self.init(code: child?.label, message: message ?? "Something went wrong. Lock and unlock Deadbolt.")
            return
        }
        self.init(code: nil, message: error.localizedDescription)
    }
}

private struct ItemsReply: Decodable { var items: [ItemSummary] }
private struct SecretReply: Decodable { var value: String }
private struct Empty: Decodable {}
private struct Head: Decodable {
    var ok: Bool
    var error: String?
}

private struct Request: Encodable {
    var op: String
    var passphrase: String?
    var query: String?
    var id: String?
    var field: String?
}

/// The Rust device owns synchronization. Slow mutations have their own queue;
/// reads and cancellation must not wait behind a KDF or pairing's network wait.
final class Core: CoreAPI, @unchecked Sendable {
    private let device: MobileDevice
    private let queue = DispatchQueue(label: "pw.deadbolt.core", qos: .userInitiated)
    /// Sync waits on the network for seconds; it runs beside everything else
    /// so search and unlock never queue behind it.
    private let syncQueue = DispatchQueue(label: "pw.deadbolt.core.sync", qos: .utility)
    private let readQueue = DispatchQueue(label: "pw.deadbolt.core.read", qos: .userInitiated, attributes: .concurrent)

    private init(device: MobileDevice) {
        self.device = device
    }

    static func open(path: String, name: String) async throws -> Core {
        try await withCheckedThrowingContinuation { continuation in
            DispatchQueue.global(qos: .userInitiated).async {
                do {
                    let device = try MobileDevice(path: path, name: name)
                    continuation.resume(returning: Core(device: device))
                } catch {
                    continuation.resume(throwing: CoreFailure(error))
                }
            }
        }
    }

    // MARK: JSON ops

    func status() async throws -> CoreStatus { try await send(Request(op: "status"), on: readQueue) }

    func joinStart(passphrase: String) async throws -> JoinStart {
        try await send(Request(op: "join-start", passphrase: passphrase))
    }

    func joinStatus() async throws -> JoinStatus { try await send(Request(op: "join-status"), on: readQueue) }

    func joinCancel() async throws {
        let _: Empty = try await send(Request(op: "join-cancel"), on: .global(qos: .userInitiated))
    }

    func unlock(passphrase: String) async throws {
        let _: Empty = try await send(Request(op: "unlock", passphrase: passphrase))
    }

    /// Lock and join-cancel skip the queue: the core cancels whatever unlock
    /// or pairing is running, so they must not wait behind it.
    func lock() async throws {
        let _: Empty = try await send(Request(op: "lock"), on: .global(qos: .userInitiated))
    }

    func sync() async throws {
        let _: Empty = try await send(Request(op: "sync"), on: syncQueue)
    }

    func foreground() async throws {
        try await run(on: .global(qos: .utility)) { try $0.foreground() }
    }

    func items(query: String) async throws -> [ItemSummary] {
        let reply: ItemsReply = try await send(Request(op: "items", query: query), on: readQueue)
        return reply.items
    }

    func item(id: String) async throws -> ItemDetail { try await send(Request(op: "item", id: id), on: readQueue) }

    func secret(id: String, field: String) async throws -> String {
        let reply: SecretReply = try await send(Request(op: "secret", id: id, field: field), on: readQueue)
        return reply.value
    }

    func code(id: String) async throws -> OneTimeCode { try await send(Request(op: "code", id: id), on: readQueue) }

    // MARK: Biometric slot

    /// Stores `token` (the Secure Enclave envelope) and a key-set slot
    /// wrapped under `key`.
    func biometricEnroll(key: Data, token: Data) async throws {
        try await run { try $0.biometricEnroll(key: key, token: token) }
    }

    func biometricToken() async throws -> Data {
        try await run { try $0.biometricToken() }
    }

    func unlockBiometric(key: Data) async throws {
        try await run { try $0.unlockBiometric(key: key) }
    }

    func approvalPending() async throws -> PendingApproval? {
        guard let json = try await run(on: readQueue, { $0.approvalPending() }) else { return nil }
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(PendingApproval.self, from: Data(json.utf8))
    }

    func approvalRespond(id: String, allow: Bool, key: Data) async throws {
        try await run(on: readQueue) { try $0.approvalRespond(id: id, allow: allow, biometricKey: key) }
    }

    func credentialIdentities() async throws -> String {
        try await run(on: .global(qos: .utility)) { try $0.credentialIdentities() }
    }

    // MARK: Plumbing

    private func send<T: Decodable>(_ request: Request, on queue: DispatchQueue? = nil) async throws -> T {
        let json = String(decoding: try JSONEncoder().encode(request), as: UTF8.self)
        let reply = try await run(on: queue) { try $0.call(request: json) }
        let bytes = Data(reply.utf8)
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        let head: Head
        do {
            head = try decoder.decode(Head.self, from: bytes)
        } catch {
            throw CoreFailure(code: nil, message: "Deadbolt couldn't read a reply. Lock and unlock it.")
        }
        guard head.ok else {
            throw CoreFailure(code: nil, message: head.error ?? "Something went wrong. Try again.")
        }
        do {
            return try decoder.decode(T.self, from: bytes)
        } catch {
            throw CoreFailure(code: nil, message: "Deadbolt couldn't read a reply. Lock and unlock it.")
        }
    }

    private func run<T: Sendable>(on queue: DispatchQueue? = nil, _ body: @escaping @Sendable (MobileDevice) throws -> T) async throws -> T {
        let device = self.device
        return try await withCheckedThrowingContinuation { continuation in
            (queue ?? self.queue).async {
                do {
                    continuation.resume(returning: try body(device))
                } catch {
                    continuation.resume(throwing: CoreFailure(error))
                }
            }
        }
    }
}

extension AppModel {
    convenience init() {
        self.init(openCore: {
            try await Core.open(path: Self.storePath(), name: UIDevice.current.name)
        }, publishIdentities: { json in
            guard let snapshot = try? JSONDecoder().decode(AutofillIdentitiesReply.self, from: Data(json.utf8)) else { return }
            await IdentitySyncer().publish(snapshot)
        })
    }
}
